// Hand-written, not generated by a bundler plugin: Turbopack (this
// project's build tool, per docs/frontend-architecture/00.md) has no
// stable Workbox/Serwist integration yet, both Serwist's webpack
// plugin and its Turbopack plugin either fail outright against this
// setup or require a still-experimental route-handler-based build
// step. This does the same real job, precache the app shell, cache
// static assets, fall back to an offline page, per
// docs/frontend-architecture/05-app-plan.md's Sub-phase 3.5, using
// the Cache API directly rather than a library.

const CACHE_VERSION = "v1";
const SHELL_CACHE = `kc-shell-${CACHE_VERSION}`;
const ASSET_CACHE = `kc-assets-${CACHE_VERSION}`;

// A fixed, explicit list rather than a build-time manifest: the app's
// entry points, offline fallback, and the wordmark/icon files from
// docs/frontend-architecture/02.md, everything else static
// (Next.js's own hashed _next/static/ chunks and fonts) gets cached
// at runtime the first time it's actually requested instead.
const APP_SHELL_URLS = [
  "/",
  "/app",
  "/offline",
  "/manifest.webmanifest",
  "/favicon.ico",
  "/wordmark-dark.svg",
  "/wordmark-light.svg",
  "/pwa/icon-192-any.png",
  "/pwa/icon-512-any.png",
  "/pwa/apple-touch-icon-180.png",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      .then((cache) => cache.addAll(APP_SHELL_URLS))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key !== SHELL_CACHE && key !== ASSET_CACHE)
            .map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

function isStaticAsset(url) {
  return (
    url.pathname.startsWith("/_next/static/") ||
    url.pathname.startsWith("/pwa/") ||
    /\.(svg|png|ico|woff2?)$/.test(url.pathname)
  );
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Only ever same-origin: the backend API lives on a different
  // origin in every environment this app runs in (see
  // NEXT_PUBLIC_API_BASE_URL in .env.example), so this check alone
  // keeps every API call, session-sensitive and always meant to be
  // fresh, un-intercepted and untouched by this cache.
  if (url.origin !== self.location.origin || request.method !== "GET") {
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(SHELL_CACHE).then((cache) => cache.put(request, copy));
          return response;
        })
        .catch(() =>
          caches.match(request).then((cached) => cached || caches.match("/offline")),
        ),
    );
    return;
  }

  if (isStaticAsset(url)) {
    event.respondWith(
      caches.match(request).then(
        (cached) =>
          cached ||
          fetch(request).then((response) => {
            const copy = response.clone();
            caches.open(ASSET_CACHE).then((cache) => cache.put(request, copy));
            return response;
          }),
      ),
    );
  }
});
